import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	if !scanner.Scan() {
		return
	}
	arr := scanner.Text()

	if !scanner.Scan() {
		return
	}
	brr := scanner.Text()

	n := len(arr)
	m := len(brr)
	ans := 0

	for i := 0; i < n; i++ {
		for j := i; j < n; j++ {
			count := 0
			for k := 0; k < n; k++ {
				if k < i || k > j {
					if count < m {
						if arr[k] == brr[count] {
							count++
						}
					} else {
						break
					}
				}
			}
			if count == m {
				length := j - i + 1
				if ans < length {
					ans = length
				}
			}
		}
	}

	fmt.Println(ans)
}

